  "claim": {
    "component_id": "C071",
    "value": "When exposure or coverage is inadequate, continued canary observation is permitted only within the safety bounds.",
    "scope": "The result remains inconclusive. The bounds concern instrumentation overhead, error rate, completion rate and tail delay against comparable baseline traffic; this does not authorize exceeding them to obtain more evidence.",
