        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P031 supplies the inconclusive result and restriction on continuation; P014 specifies the bounds, and P030 identifies the canary context."
    }
  },
  "signal_basis": {
    "component_id": "C071_SIGNAL",
    "value": "Canary exposure or coverage is inadequate for a conclusive judgment under the specified observation window and required exposure.",
    "scope": "Insufficient observation leaves the result inconclusive. Continuation must respect predefined safety bounds; breached bounds or inability to enforce them require halting expansion and reverting the canary.",
